class Solution:
    def countPyramids(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        def count_from(r0, c0, dr):
            height = 1
            while True:
                r = r0 + dr * height
                if r < 0 or r >= m:
                    break
                lo, hi = c0 - height, c0 + height
                if lo < 0 or hi >= n:
                    break
                if any(grid[r][c] == 0 for c in range(lo, hi + 1)):
                    break
                height += 1
            return height - 1

        total = 0
        for r in range(m):
            for c in range(n):
                if grid[r][c]:
                    total += count_from(r, c, 1) + count_from(r, c, -1)
        return total

