            if (r < 0 || r >= m) break;
            int lo = c0 - height, hi = c0 + height;
            if (lo < 0 || hi >= n) break;
            bool ok = true;
            for (int c = lo; c <= hi; c++) {
                if (!grid[r][c]) { ok = false; break; }
            }
            if (!ok) break;
            height++;
        }
        return height - 1;
    }

