class Solution:
    def countPyramids(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        total = 0

        dp = [row[:] for row in grid]
        for r in range(m - 2, -1, -1):
            for c in range(1, n - 1):
                if dp[r][c]:
                    dp[r][c] = 1 + min(dp[r + 1][c - 1], dp[r + 1][c], dp[r + 1][c + 1])
                    total += dp[r][c] - 1

        dp = [row[:] for row in grid]
        for r in range(1, m):
            for c in range(1, n - 1):
                if dp[r][c]:
                    dp[r][c] = 1 + min(dp[r - 1][c - 1], dp[r - 1][c], dp[r - 1][c + 1])
                    total += dp[r][c] - 1

        return total

