class Solution {
    public int countPyramids(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int total = 0;

        int[][] dp = new int[m][];
        for (int i = 0; i < m; i++) dp[i] = grid[i].clone();
        for (int r = m - 2; r >= 0; r--)
            for (int c = 1; c + 1 < n; c++)
                if (dp[r][c] == 1) {
                    dp[r][c] = 1 + Math.min(dp[r + 1][c - 1],
                                Math.min(dp[r + 1][c], dp[r + 1][c + 1]));
                    total += dp[r][c] - 1;
                }

        for (int i = 0; i < m; i++) dp[i] = grid[i].clone();
        for (int r = 1; r < m; r++)
            for (int c = 1; c + 1 < n; c++)
                if (dp[r][c] == 1) {
                    dp[r][c] = 1 + Math.min(dp[r - 1][c - 1],
                                Math.min(dp[r - 1][c], dp[r - 1][c + 1]));
                    total += dp[r][c] - 1;
                }

        return total;
    }
};

